-- Install snippets for the README, generated by nvim-install-snippets.
-- Regenerate after editing: nvim-install-snippets generate
return {
  repo = "tytrdev/lean-voice",
  main = "lean_voice",
  build = "uv sync",
  -- setup() only defines keymaps, a command and an autocmd, so load early:
  -- lazy-loading on ft hides :checkhealth, :help and :LeanVoice setup until a Lean file opens.
  lazy = {
    event = "VeryLazy",
    cmd = "LeanVoice",
    keys = { "<leader>vv", "<leader>vo", "<leader>vc" },
  },
  readme = { layout = "accordion" },
  variants = {
    minimal = { opts = {} },
    full = {
      label = "With every option and claudecode.nvim",
      dependencies = { "coder/claudecode.nvim", "folke/snacks.nvim" },
      -- claudecode.nvim lets Claude see your file, cursor and selection; Claude runs in its own pane.
      config = 'require("claudecode").setup({ terminal = { provider = "none" } })',
      opts = {
        autosave = true,
        keys = { talk = "<leader>vv", toggle = "<leader>vo", voice = "<leader>vc" },
      },
    },
  },
}
